import { readFileSync } from "node:fs";
import { join } from "node:path";
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

/**
 * Serves a strict Content-Security-Policy with build-time script hashes
 * (generated by scripts/build-csp-hashes.ts into csp-hashes.json), so pages
 * stay statically generated — no nonce, no 'unsafe-inline' scripts.
 * See node_modules/next/dist/docs/01-app/02-guides/content-security-policy.md.
 */

type Manifest = { routes: Record<string, string[]>; fallback: string[] };

function loadManifest(): Manifest {
  try {
    return JSON.parse(readFileSync(join(process.cwd(), "csp-hashes.json"), "utf8")) as Manifest;
  } catch {
    return { routes: {}, fallback: [] };
  }
}

const manifest = loadManifest();
const isDev = process.env.NODE_ENV === "development";

const BASE_DIRECTIVES = [
  "default-src 'self'",
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self' data: blob:",
  "font-src 'self'",
  "object-src 'none'",
  "base-uri 'self'",
  "form-action 'self'",
  "frame-ancestors 'none'",
];

function cspFor(pathname: string): string {
  if (isDev) {
    return [
      ...BASE_DIRECTIVES,
      "script-src 'self' 'unsafe-inline' 'unsafe-eval'",
      "connect-src 'self' ws:",
    ].join("; ");
  }
  const hashes = manifest.routes[pathname] ?? manifest.fallback;
  const scriptSrc = ["'self'", ...hashes.map((h) => `'sha256-${h}'`)].join(" ");
  return [...BASE_DIRECTIVES, `script-src ${scriptSrc}`, "connect-src 'self'", "upgrade-insecure-requests"].join("; ");
}

export function proxy(request: NextRequest) {
  const response = NextResponse.next();
  response.headers.set("Content-Security-Policy", cspFor(request.nextUrl.pathname));
  return response;
}

export const config = {
  matcher: "/((?!api|_next/static|_next/image|favicon.ico|cv|og).*)",
};
